// Correcciones Simulia — tanda 3 — parte 3 de 7: protocolos y escalas (preguntas propias) (10 oct 2026)
// Pegar en mongosh (Compass) conectado a SimuLIA. Guarda copia de cada original antes de tocarlo.
const db2 = db.getSiblingDB('CSV');
const backup = db2.getCollection('backup_correcciones_2026_10_10_t3');
let ok=0, del=0, warn=0;
function fix(coll, filter, set) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], savedAt: new Date() });
  c.updateOne({ _id: d[0]._id }, { $set: set }); ok++;
}
function rm(coll, filter) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], deleted: true, savedAt: new Date() });
  c.deleteOne({ _id: d[0]._id }); del++;
}

fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977832") }, {"long_answer": "La vía clínica RICA recomienda técnicas de cierre esternal reforzado, como el cierre con alambres cruzados (en ocho), para reducir las complicaciones esternales en cirugía cardíaca, especialmente en pacientes de alto riesgo como obesos, diabéticos o con EPOC. Este tipo de cierre aporta mayor estabilidad mecánica al esternón, lo que disminuye la dehiscencia y la infección esternal profunda. El cierre con alambres simples ofrece menor estabilidad en pacientes de riesgo, y las grapas metálicas o las suturas absorbibles no se recomiendan para la aproximación del esternón."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977834") }, {"long_answer": "Para prevenir el daño renal agudo tras cirugía cardíaca, la vía clínica RICA recomienda aplicar el paquete de medidas de protección renal basado en el estudio PrevAKI, que incluye evitar fármacos nefrotóxicos, suspender IECA y ARA II, optimizar la volemia y la perfusión, monitorizar creatinina y diuresis y evitar la hiperglucemia en los pacientes de riesgo. Evitar los líquidos intravenosos favorecería la hipoperfusión renal. La ultrafiltración con balance cero y la monitorización con PiCCO no son las medidas preventivas recomendadas de forma general."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977835") }, {"long_answer": "La escala CAM-ICU (Confusion Assessment Method for the Intensive Care Unit) es la herramienta recomendada en la vía RICA para la detección del delirium en el postoperatorio de cirugía cardíaca. Está validada en pacientes críticos, incluso intubados, y valora el inicio agudo o curso fluctuante, la inatención, el pensamiento desorganizado y la alteración del nivel de conciencia. La escala de Beck evalúa depresión, las escalas de dolor miden la intensidad del dolor y la escala de Glasgow valora el nivel de conciencia, pero ninguna de ellas diagnostica delirium."});
rm('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97783a") });
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977841") }, {"long_answer": "La vía clínica RICA recomienda una analgesia multimodal ahorradora de opioides, en la que la combinación de paracetamol y AINEs, salvo contraindicación, constituye la base del control del dolor postoperatorio, junto con técnicas de anestesia locorregional. Así se reduce el consumo de opioides y sus efectos adversos, como náuseas, íleo o depresión respiratoria. El reposo en cama prolongado está desaconsejado porque la movilización precoz es un pilar de la recuperación intensificada, el uso rutinario de gabapentinoides no se recomienda y el uso elevado de opioides intravenosos va en contra de la estrategia multimodal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977848") }, {"long_answer": "La vía clínica RICA desaconseja el uso rutinario de benzodiacepinas antes de la inducción anestésica, especialmente las de acción prolongada y en pacientes mayores, por su asociación con delirium, sedación residual y retraso en la recuperación. Si son necesarias para controlar la ansiedad, deben emplearse de acción corta y a la mínima dosis posible. Usar la dosis máxima o mantenerlas durante toda la cirugía aumenta los efectos adversos, y la prohibición absoluta no refleja la recomendación, que permite su uso puntual y prudente en casos seleccionados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97784e") }, {"option_1": "Para ajustar la dosis de los relajantes musculares", "long_answer": "La vía clínica RICA recomienda monitorizar la temperatura en todo paciente sometido a anestesia general de más de 30 minutos con el fin de aplicar medidas tempranas para evitar la hipotermia. La hipotermia perioperatoria aumenta la infección del sitio quirúrgico, el sangrado, los eventos cardíacos y prolonga la recuperación, por lo que su detección precoz permite activar el calentamiento activo. La monitorización térmica no sirve para ajustar la dosis de relajantes musculares, la fiebre no es el objetivo principal en el intraoperatorio y la presión arterial se monitoriza con otros dispositivos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97784f") }, {"long_answer": "Según la vía clínica RICA, las estrategias de calentamiento activo deben iniciarse entre 20 y 30 minutos antes de la cirugía. Este precalentamiento con mantas de aire forzado reduce el gradiente térmico entre el compartimento central y la periferia, lo que limita la caída de temperatura que se produce tras la inducción anestésica por la redistribución del calor. Un periodo de solo 10 a 20 minutos resulta menos eficaz, y los intervalos de 30 a 40 o de 40 a 50 minutos no son los establecidos en la recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977853") }, {"option_2": "Ayuno absoluto de sólidos y líquidos desde la medianoche", "long_answer": "Antes del ingreso ambulatorio, la vía RICA recomienda que el paciente realice una ducha completa la noche anterior a la intervención, como medida de higiene para disminuir la carga bacteriana de la piel y prevenir la infección del sitio quirúrgico. El ayuno desde la medianoche está desaconsejado, ya que se permiten sólidos hasta 6 horas y líquidos claros hasta 2 horas antes. La profilaxis tromboembólica y la colocación de medias o compresión neumática se indican según el riesgo del paciente y se gestionan en el ámbito hospitalario."});
rm('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977857") });
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97785a") }, {"question": "Según la figura 13 del informe de VIH y sida 2023, ¿qué porcentaje de los nuevos diagnósticos en hombres heterosexuales presentaba más de 500 CD4/µl?", "long_answer": "En la figura 13 del informe de vigilancia del VIH y sida 2023 se representa la distribución de los nuevos diagnósticos según el recuento de linfocitos CD4 al diagnóstico. En los hombres heterosexuales, solo el 19,2% presentaba más de 500 CD4/µl, lo que refleja que este grupo se diagnostica con frecuencia en fases avanzadas y acumula una de las mayores proporciones de diagnóstico tardío (menos de 350 CD4/µl). Los valores de 47,9%, 57,8% y 59,9% corresponden a proporciones de diagnóstico tardío o de otros grupos de transmisión."});
rm('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97785e") });
rm('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977862") });
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977869") }, {"long_answer": "Según el informe de vigilancia del VIH y sida 2023, el grupo de 15 a 29 años es en el que la mediana del recuento de CD4 al diagnóstico ha descendido a lo largo del periodo analizado. Este dato es preocupante porque sugiere que en los jóvenes la infección se está detectando más tarde, lo que refuerza la necesidad de promover la realización de la prueba del VIH en este grupo. En los grupos de 30-34, 35-49 y 50 o más años no se describe ese descenso de la mediana."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97786d") }, {"long_answer": "Según el informe de vigilancia epidemiológica del VIH y sida en España de 2023, el 86,1% de los nuevos diagnósticos de VIH se produjo en hombres y el 13,9% en mujeres. Este marcado predominio masculino se explica principalmente por el peso de la transmisión en hombres que tienen relaciones sexuales con hombres, que constituye el modo de transmisión más frecuente. Las distribuciones de 75/25, 80/20 invertida o 90/10 no se corresponden con los datos publicados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977871") }, {"long_answer": "El informe de vigilancia del VIH y sida en España de 2023 sitúa en el 48,7% la proporción de nuevos diagnósticos con diagnóstico tardío, definido como un recuento inferior a 350 linfocitos CD4/µl en la primera determinación tras el diagnóstico. Prácticamente la mitad de los casos se detecta tarde, lo que empeora el pronóstico individual y favorece la transmisión, por lo que se insiste en ampliar la oferta de la prueba. Los valores redondeados de 40%, 45% y 50% no se corresponden con el dato publicado."});
rm('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97787f") });
rm('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977881") });
rm('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977884") });
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977887") }, {"long_answer": "Según la encuesta del proyecto PREVEMED, la principal limitación señalada para la puesta en marcha de tecnologías relacionadas con la prevención de errores de medicación fue el presupuesto insuficiente. Sistemas como la prescripción electrónica, los armarios automatizados de dispensación, la verificación por código de barras o las bombas de infusión inteligentes requieren una inversión elevada. La falta de formación, las dificultades logísticas y la ausencia de regulación nacional fueron también mencionadas, pero en menor proporción que la limitación económica."});
